// Checks for saving: the local server keeps events in plain files, one per person, and gives them back.
// Run: npm test (Node 18+). Uses a throwaway data folder, never the real one.
// Code generated by Claude (Anthropic), an AI system.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readdir, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const APP = fileURLToPath(new URL('..', import.meta.url));

async function startServer(dataDir) {
  const port = 20000 + Math.floor(Math.random() * 20000);
  const child = spawn(process.execPath, ['serve.mjs'], { cwd: APP, env: { ...process.env, PORT: String(port), DATA_DIR: dataDir }, stdio: ['ignore', 'pipe', 'pipe'] });
  await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('server did not start')), 5000);
    child.stdout.on('data', (d) => { if (String(d).includes('running')) { clearTimeout(timer); resolve(); } });
    child.on('exit', (code) => { clearTimeout(timer); reject(new Error(`server exited ${code}`)); });
  });
  return { base: `http://127.0.0.1:${port}`, stop: () => child.kill() };
}

const event = (person, value, time) => ({
  v: 1, kind: 'reading', time, person,
  state: { aiWorks: true, doctorOnBoard: false, linkToEarth: true },
  reading: { source: 'pulse-meter', indicator: 'pulse', value },
});

test('saved events come back, in time order, and live in one plain file per person named by id', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jff-data-'));
  const srv = await startServer(dir);
  try {
    const post = (e) => fetch(`${srv.base}/api/events`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(e) });
    assert.equal((await post(event('crew-1', 80, '2026-03-02T08:00:00.000Z'))).status, 204);
    assert.equal((await post(event('crew-1', 70, '2026-03-01T08:00:00.000Z'))).status, 204);
    assert.equal((await post(event('crew-2', 65, '2026-03-01T09:00:00.000Z'))).status, 204);
    const back = await (await fetch(`${srv.base}/api/events`)).json();
    assert.deepEqual(back.map((e) => e.reading.value), [70, 65, 80]);
    const files = (await readdir(dir)).sort();
    assert.deepEqual(files, ['crew-1.jsonl', 'crew-2.jsonl']);
    const lines = (await readFile(join(dir, 'crew-1.jsonl'), 'utf8')).trim().split('\n');
    assert.equal(lines.length, 2);
  } finally {
    srv.stop();
    await rm(dir, { recursive: true, force: true });
  }
});

test('the server refuses anything that is not a valid event, and never serves the data folder', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jff-data-'));
  const srv = await startServer(dir);
  try {
    const post = (body) => fetch(`${srv.base}/api/events`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body });
    const bad = [
      'not json',
      JSON.stringify({ ...event('crew-1', 70, '2026-03-01T08:00:00.000Z'), person: '../../evil' }),
      JSON.stringify({ ...event('crew-1', 70, '2026-03-01T08:00:00.000Z'), time: 'yesterday' }),
      JSON.stringify({ ...event('crew-1', 70, '2026-03-01T08:00:00.000Z'), kind: 'delete-everything' }),
      JSON.stringify({ ...event('crew-1', 70, '2026-03-01T08:00:00.000Z'), v: 2 }),
    ];
    for (const body of bad) assert.equal((await post(body)).status, 400, body);
    assert.deepEqual(await readdir(dir), []);
    assert.equal((await fetch(`${srv.base}/data/crew-1.jsonl`)).status, 404);
    assert.equal((await fetch(`${srv.base}/tests/serve.test.js`)).status, 404);
    assert.equal((await fetch(`${srv.base}/`)).status, 200);
  } finally {
    srv.stop();
    await rm(dir, { recursive: true, force: true });
  }
});
